CREATE OR REPLACE FUNCTION public.pay_common_package_refund_reject(p_actor uuid, p_order uuid, p_ticket uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
