 PERFORM 1 FROM profiles WHERE id=(SELECT user_id FROM payment_orders WHERE id=p_order) FOR UPDATE;
 SELECT * INTO o FROM payment_orders WHERE id=p_order FOR UPDATE;
 IF NOT FOUND OR o.item_type IS DISTINCT FROM 'credit_package' AND NOT (o.item_type='membership_plan' AND (o.payment_channel='stripe' AND o.payment_method IN ('wechat_pay','alipay') OR o.payment_channel='waffo'
